function f_{SUT}_CMN_PR_InitConfiguration_001() runs on {SUT}Tester {
    timer t_sdp := 5.0;
    t_sdp.start;
    pt_V2G_UDP_SDP_Port.send(construct_sdp_request());
    alt {
        [] pt_V2G_UDP_SDP_Port.receive(?) {
            t_sdp.stop;
            log("SDP response received");
        }
        [] t_sdp.timeout {
            log("SDP timeout, proceeding...");
        }
    }
}

// V2GTP Header: 8 bytes total
// Bytes 0-1: protocolVersion='01'O, invProtocolVersion='FE'O
// Bytes 2-3: payloadType (see SOP protocol_constants)
// Bytes 4-7: payloadLength as 4-byte big-endian integer
// CRITICAL: Use a REAL, valid ISO 15118-2 EXI octetstring as the payload.
// NEVER use dummy placeholders like '0022'O -- they will cause the SECC simulator
// to crash its EXI decoder and drop the TCP connection, resulting in 'inconc'.
// NOTE: The EXI payload hex string MUST have an even number of hex characters.
// If the raw EXI string has odd length, pad with '0' or '00' at the end before compiling.
var octetstring exi_payload := '8000EBAB9371D34B9B79D189A98989C1D191D191818999D26B9B3A232B30020000000001B75726E3A64696E3A37303132313A323031323A4D73674465660040000000880000'O; // Valid SupportedAppProtocolReq EXI (140 bytes, 280 hex chars)
var octetstring v2gtp_msg := '01'O & 'FE'O & {payloadType} & int2oct(lengthof(exi_payload), 4) & exi_payload;
{port_name}.send(v2gtp_msg);

// TCP connect block (handled by port adapter based on set_parameter ip_address/port)
// The C++ port adapter reads V2G__UDP__SDP__Port__last_secc_ip_ and V2G__UDP__SDP__Port__last_secc_port_
// to determine the TCP destination after SDP response is received.
// In TTCN-3: just ensure the port is mapped and parameters are set.
map(mtc:pt_V2G_TCP_TLS_ALM_{SUT}_Port, system:pt_V2G_TCP_TLS_ALM_{SUT}_Port);
// Port adapter will establish TCP connection on first send() using shared SDP state

timer tc_msg := {timer_value};
tc_msg.start;
{port_name}.send(v2gtp_msg);
alt {
    [] {port_name}.receive({expected_template}) {
        tc_msg.stop;
        setverdict(pass, "{success_message}");
    }
    [] {port_name}.receive(?) {
        tc_msg.stop;
        setverdict(fail, "{failure_message}");
    }
    [] tc_msg.timeout {
        setverdict(inconc, "Timeout waiting for response");
    }
}
return getverdict;

// Phase A: Map ports (at beginning of testcase)
map(mtc:pt_V2G_TCP_TLS_ALM_{SUT}_Port, system:pt_V2G_TCP_TLS_ALM_{SUT}_Port);
map(mtc:pt_V2G_UDP_SDP_Port, system:pt_V2G_UDP_SDP_Port);

// Phase D: Unmap ports (at end of testcase, unconditional)
f_{SUT}_CMN_PO_Default_001();
unmap(mtc:pt_V2G_TCP_TLS_ALM_{SUT}_Port, system:pt_V2G_TCP_TLS_ALM_{SUT}_Port);
unmap(mtc:pt_V2G_UDP_SDP_Port, system:pt_V2G_UDP_SDP_Port);

// GoodCase: expect valid response
var verdicttype v_result;
alt {
    [] {port_name}.receive({expected_response}) {
        tc_msg.stop;
        setverdict(pass, "Response matches expected");
        v_result := pass;
    }
    [] {port_name}.receive(?) {
        tc_msg.stop;
        setverdict(fail, "Unexpected response received");
        v_result := fail;
    }
    [] tc_msg.timeout {
        setverdict(inconc, "Timeout waiting for response");
        v_result := inconc;
    }
    // Note: connection closed is handled by the C++ adapter as unexpected message
}

// BadCase: expect SUT to reject/ignore/close
var verdicttype v_result;
alt {
    [] {port_name}.receive({error_rejection_template}) {
        tc_msg.stop;
        setverdict(pass, "SUT correctly rejected invalid input");
        v_result := pass;
    }
    [] {port_name}.receive(?) {
        tc_msg.stop;
        setverdict(fail, "SUT should reject this invalid input");
        v_result := fail;
    }
    [] tc_msg.timeout {
        setverdict(pass, "SUT correctly ignored invalid input (timeout)");
        v_result := pass;
    }
}

function f_{SUT}_{Category}_TB_VTB_{MessageType}_{SeqNo}() runs on {SUT}Tester {
    timer tc_msg := {timer_value};
    tc_msg.start;
    // CRITICAL: Use real valid EXI -- never '0022'O or other placeholders.
    // NOTE: EXI payload hex string MUST have an even number of hex characters.
    // If the raw EXI string has odd length, pad with '0' or '00' at the end.
    var octetstring exi_payload := '8000EBAB9371D34B9B79D189A98989C1D191D191818999D26B9B3A232B30020000000001B75726E3A64696E3A37303132313A323031323A4D73674465660040000000880000'O; // Valid SupportedAppProtocolReq EXI (140 bytes, 280 hex chars)
    var octetstring v2gtp := '01'O & 'FE'O & '8001'O & int2oct(lengthof(exi_payload), 4) & exi_payload;
    {port_name}.send(v2gtp);
    // ... alt block ...
    return getverdict;
}

function f_{SUT}_CMN_PR_{MessageName}_{SeqNo}() runs on {SUT}Tester {
    // Implement the specific protocol step for {MessageName}
    // Send V2GTP-wrapped {MessageName}Req, receive {MessageName}Res
    timer tc_step := {timeout};
    tc_step.start;
    var octetstring req := '01'O & 'FE'O & '8001'O & int2oct(lengthof(exi_req), 4) & exi_req;
    {port_name}.send(req);
    alt {
        [] {port_name}.receive(?) -> value v_resp {
            tc_step.stop;
            // Manually check V2GTP header (cannot use ? with & in templates)
            if (lengthof(v_resp) >= 4 and substr(v_resp, 0, 1) == '01'O
                and substr(v_resp, 1, 1) == 'FE'O) {
                log("{MessageName} exchange completed");
            } else {
                log("{MessageName}: unexpected response");
            }
        }
        [] tc_step.timeout {
            log("{MessageName} precondition timeout");
        }
    }
}

// Phase B: Preconditions (conditional on success)
var verdicttype preConVerdict := pass;
if (f_SECC_CMN_PR_InitConfiguration_001() != pass) {
    preConVerdict := fail;
}

// Phase C: Test behavior (only if preconditions passed)
var verdicttype v_result := fail;
if (preConVerdict == pass) {
    v_result := f_SECC_CMN_TB_VTB_{MsgType}_{SeqNo}();
    setverdict(v_result);
}

// Phase D: Postconditions (ALWAYS runs, regardless of preConVerdict or v_result)
f_SECC_CMN_PO_Default_001();
unmap(mtc:pt_V2G_TCP_TLS_ALM_SECC_Port, system:pt_V2G_TCP_TLS_ALM_SECC_Port);
unmap(mtc:pt_V2G_UDP_SDP_Port, system:pt_V2G_UDP_SDP_Port);
